/**
 * One-shot generator of the frozen mutation-sequence fixtures (#854 phase 4,
 * S00). Run it once, against the OLD fold, with:
 *
 *   bun src/services/history/__tests__/mutationSequence.generate.ts --write
 *
 * The JSON it writes is the oracle the new journal store must reproduce. It
 * is never regenerated by an implementer; it is deleted with the old fold in
 * S14 (the fixtures stay). Without --write it prints a summary only.
 */
import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  runMutationSequence,
  type FixtureStep,
  type MutationSequenceFixture,
  type MutationStep,
  type RowSpec,
  type StepObservation,
  observationOfTags,
} from './support/mutationSequence.js';

const FIXTURE_DIR = path.join(
  path.dirname(fileURLToPath(import.meta.url)),
  'fixtures',
  'mutation-sequence',
);

const human = (text: string): RowSpec => ({ speaker: 'human', text });
const ai = (text: string): RowSpec => ({ speaker: 'ai', text });
const call = (id: string): RowSpec => ({
  speaker: 'ai',
  call: { id, name: 'read_file' },
});
const response = (id: string): RowSpec => ({
  speaker: 'tool',
  text: `result-${id}`,
  response: { callId: id, name: 'read_file' },
});

interface Scenario {
  readonly name: string;
  readonly description: string;
  readonly steps: readonly MutationStep[];
}

