/** Seeded generator, so the random sequences are reproducible. */
function mulberry32(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function randomSteps(seed: number, length: number): MutationStep[] {
  const next = mulberry32(seed);
  const pick = (limit: number): number => Math.floor(next() * limit);
  const steps: MutationStep[] = [{ op: 'fill', count: 4, prefix: `s${seed}` }];
  let rows = 4;
  let counter = 0;
  while (steps.length < length) {
    counter += 1;
    const choice = pick(10);
    if (choice < 3) {
      steps.push({ op: 'add', row: human(`s${seed}-add-${counter}`) });
      rows += 1;
    } else if (choice === 3 && rows > 0) {
      steps.push({ op: 'pop' });
      rows -= 1;
    } else if (choice === 4 && rows > 1) {
      const keep = pick(rows);
      steps.push({ op: 'truncate', keep });
      rows = keep;
    } else if (choice === 5 && rows > 2) {
      steps.push({
        op: 'density',
        removals: [pick(rows)],
        replacements: [],
      });
      rows -= 1;
    } else if (choice === 6) {
      steps.push({ op: 'compress', summary: ai(`s${seed}-sum-${counter}`) });
      rows = 1;
    } else if (choice === 7) {
      steps.push({
        op: 'addAll',
        rows: [human(`s${seed}-q-${counter}`), ai(`s${seed}-a-${counter}`)],
      });
      rows += 2;
    } else if (choice === 8 && rows > 0) {
      steps.push({ op: 'removeLast' });
      rows -= 1;
    } else if (choice === 9 && next() < 0.3) {
      steps.push({ op: 'clear' });
      rows = 0;
    }
  }
  return steps;
}

const SEEDS = [11, 23, 37, 41, 59, 71];

function allScenarios(): readonly Scenario[] {
  return [
    ...SCENARIOS,
    ...SEEDS.map(
      (seed): Scenario => ({
        name: `seeded-${seed}`,
        description: `random mutation sequence, seed ${seed}`,
        steps: randomSteps(seed, 14),
      }),
    ),
  ];
}

/**
 * Corrected expectation for known-defect-2, from an array model: the live
 * rows before the sequence's pops are right, and a pop removes exactly the
 * last row (the row at the popped-to label), never the rows after the first
 * row that repeats its chronology marker.
 */
function correctedDefect2(
  steps: readonly MutationStep[],
  observed: readonly StepObservation[],
): StepObservation[] {
  const corrected: StepObservation[] = [];
  let tags: readonly string[] = [];
  steps.forEach((step, index) => {
    const live = observed[index].live;
    if (step.op === 'pop') tags = tags.slice(0, -1);
    else if (live.tags === undefined)
      throw new Error('known-defect-2 needs per-row tags');
    else tags = live.tags;
    const expected = observationOfTags(tags);
    corrected.push({ live: expected, resumed: expected });
  });
  return corrected;
}

async function generate(scenario: Scenario): Promise<MutationSequenceFixture> {
  const observed = await runMutationSequence(scenario.steps);
  const steps: FixtureStep[] = scenario.steps.map((step, index) => ({
    step,
    observed: observed[index],
  }));
  const base = {
    name: scenario.name,
    description: scenario.description,
    steps,
  };
  return scenario.name === 'known-defect-2'
    ? { ...base, corrected: correctedDefect2(scenario.steps, observed) }
    : base;
}

async function main(): Promise<void> {
  const write = process.argv.includes('--write');
  if (write) await fs.mkdir(FIXTURE_DIR, { recursive: true });
  for (const scenario of allScenarios()) {
    const fixture = await generate(scenario);
    const last = fixture.steps[fixture.steps.length - 1].observed;
    process.stdout.write(
      `${scenario.name}: ${fixture.steps.length} steps, live ${last.live.length}, resumed ${last.resumed.length}\n`,
    );
    if (write)
      await fs.writeFile(
        path.join(FIXTURE_DIR, `${scenario.name}.json`),
        `${JSON.stringify(fixture, null, 2)}\n`,
      );
  }
}

await main();
